import pytest

from src import disclosure
from tests.helpers import make_draft


@pytest.mark.parametrize('sentence', [
    '이 글은 AI의 도움을 받아 작성했습니다.',
    '본 포스팅은 ChatGPT로 정리한 내용입니다.',
    '이 글은 인공지능이 작성한 글입니다.',
    'AI가 작성한 글입니다.',
    '(Generated by AI)',
    'This post was written by AI.',
    '※ AI로 생성된 콘텐츠입니다.',
])
def test_detects_self_disclosure(sentence):
    assert disclosure.is_ai_disclosure(sentence)


@pytest.mark.parametrize('sentence', [
    'AI가 만든 이미지를 구별하는 방법이 화제입니다.',
    '회의록 자동 생성 기능이 추가됐습니다.',
    'README가 너무 깔끔하면 AI-generated일 가능성이 있습니다.',
    '챗GPT로 보고서 초안을 쓰는 직장인이 늘었습니다.',
    '내년부터 AI로 생성된 콘텐츠에는 표시 의무가 생깁니다.',
    'AI로 생성한 이미지를 구별하는 법을 정리했습니다.',
    '해당 콘텐츠는 AI로 제작된 것으로 드러났습니다.',
])
def test_keeps_normal_ai_content(sentence):
    assert not disclosure.is_ai_disclosure(sentence)


def test_strip_removes_only_disclosure_sentences_from_all_prose():
    hook = '출근길이 두 배로 길어졌다면?\n\n이 글은 AI의 도움을 받아 작성했습니다. 답은 시간대에 있습니다.'
    draft = make_draft(hook=hook, why_it_matters='교통비가 줄어듭니다. (Generated by AI)',
                       action_items=['이번 달 이용 횟수를 확인하세요.', 'AI가 작성한 글입니다.'],
                       image_alt='책상 사진 (AI 생성 이미지)')
    clean = disclosure.strip_ai_disclosure(draft)
    assert clean.hook == '출근길이 두 배로 길어졌다면?\n\n답은 시간대에 있습니다.'
    assert clean.why_it_matters == '교통비가 줄어듭니다.'
    assert clean.action_items == ['이번 달 이용 횟수를 확인하세요.']
    assert clean.image_alt == '책상 사진'
    assert clean.sections == draft.sections  # 문제없는 부분은 그대로


def test_strip_leaves_clean_draft_untouched():
    draft = make_draft()
    assert disclosure.strip_ai_disclosure(draft) == draft


def test_clean_text_never_drops_other_characters():
    text = '괄호 (예: 광역버스) 안도 그대로. 끝에 문장부호 없음'
    assert disclosure.clean_text(text + ' (Generated by AI)') == text
